package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct {
	ArAcct string
	ArAmt  decimal.Decimal
}

var WsEofFlag string = "N"
var WsBigTotal decimal.Decimal = decimal.Zero
var WsWrapTotal decimal.Decimal = decimal.Zero
var WsSafeTotal decimal.Decimal = decimal.Zero
var WsOverflows int64 = 0
var WsCount int64 = 0
var WsHalf decimal.Decimal = decimal.Zero
var WsAmtEd string
var WsWrapEd string
var WsSafeEd string
var WsHalfEd string

var CurRec AmtRec
var amtLines []string
var amtIdx int

func inputDone() bool { return WsEofFlag == "Y" }

func wrapDecimal(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	t := v.Truncate(int32(scale))
	scaled := t.Shift(int32(scale)).IntPart()
	var factor int64 = 1
	for i := 0; i < intDigits+scale; i++ {
		factor *= 10
	}
	mod := scaled % factor
	return decimal.New(mod, int32(-scale))
}

func isSizeError(v decimal.Decimal, intDigits int, scale int) bool {
	t := v.Truncate(int32(scale))
	if t.Sign() < 0 {
		return true
	}
	var factor int64 = 1
	for i := 0; i < intDigits+scale; i++ {
		factor *= 10
	}
	maxScaled := factor - 1
	scaled := t.Shift(int32(scale)).IntPart()
	if scaled > maxScaled {
		return true
	}
	return false
}

func formatZZZZ9_99(d decimal.Decimal) string {
	v := d.Truncate(2)
	scaled := v.Shift(2).IntPart()
	neg := scaled < 0
	if neg {
		scaled = -scaled
	}
	intPart := scaled / 100
	fracPart := scaled % 100
	intMod := intPart % 100000
	digits := make([]int, 5)
	tmp := intMod
	for i := 4; i >= 0; i-- {
		digits[i] = int(tmp % 10)
		tmp /= 10
	}
	firstNZ := 4
	for i := 0; i < 5; i++ {
		if digits[i] != 0 {
			firstNZ = i
			break
		}
	}
	var chars [6]byte
	if 0 < firstNZ {
		chars[0] = ' '
	} else {
		chars[0] = byte('0' + digits[0])
	}
	if 1 < firstNZ {
		chars[1] = ' '
	} else {
		chars[1] = byte('0' + digits[1])
	}
	if firstNZ > 1 {
		chars[2] = ' '
	} else {
		chars[2] = ','
	}
	if 2 < firstNZ {
		chars[3] = ' '
	} else {
		chars[3] = byte('0' + digits[2])
	}
	if 3 < firstNZ {
		chars[4] = ' '
	} else {
		chars[4] = byte('0' + digits[3])
	}
	chars[5] = byte('0' + digits[4])
	intStr := string(chars[:])
	fracStr := fmt.Sprintf("%02d", fracPart)
	return intStr + "." + fracStr
}

func formatZZZZ9_9(d decimal.Decimal) string {
	v := d.Truncate(1)
	scaled := v.Shift(1).IntPart()
	if scaled < 0 {
		scaled = -scaled
	}
	intPart := scaled / 10
	fracPart := scaled % 10
	intMod := intPart % 100000
	digits := make([]int, 5)
	tmp := intMod
	for i := 4; i >= 0; i-- {
		digits[i] = int(tmp % 10)
		tmp /= 10
	}
	firstNZ := 4
	for i := 0; i < 5; i++ {
		if digits[i] != 0 {
			firstNZ = i
			break
		}
	}
	var chars [6]byte
	if 0 < firstNZ {
		chars[0] = ' '
	} else {
		chars[0] = byte('0' + digits[0])
	}
	if 1 < firstNZ {
		chars[1] = ' '
	} else {
		chars[1] = byte('0' + digits[1])
	}
	if firstNZ > 1 {
		chars[2] = ' '
	} else {
		chars[2] = ','
	}
	if 2 < firstNZ {
		chars[3] = ' '
	} else {
		chars[3] = byte('0' + digits[2])
	}
	if 3 < firstNZ {
		chars[4] = ' '
	} else {
		chars[4] = byte('0' + digits[3])
	}
	chars[5] = byte('0' + digits[4])
	intStr := string(chars[:])
	return intStr + "." + fmt.Sprintf("%01d", fracPart)
}

func MainPara() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	s := string(data)
	amtLines = nil
	amtIdx = 0
	if len(s) != 0 {
		parts := strings.Split(s, "\n")
		for i, p := range parts {
			if i == len(parts)-1 && p == "" && len(s) > 0 && s[len(s)-1] == '\n' {
				continue
			}
			if strings.HasSuffix(p, "\r") {
				p = p[:len(p)-1]
			}
			amtLines = append(amtLines, p)
		}
	}
	ReadPara()
	for !inputDone() {
		ProcessPara()
	}
	SummaryPara()
}

func ReadPara() {
	if amtIdx < len(amtLines) {
		line := amtLines[amtIdx]
		amtIdx++
		if len(line) < 11 {
			line += strings.Repeat(" ", 11-len(line))
		} else if len(line) > 11 {
			line = line[:11]
		}
		acct := line[0:4]
		amtStr := line[4:11]
		var n int64 = 0
		for i := 0; i < 7; i++ {
			c := amtStr[i]
			if c >= '0' && c <= '9' {
				n = n*10 + int64(c-'0')
			} else {
				n = n * 10
			}
		}
		CurRec.ArAcct = acct
		CurRec.ArAmt = decimal.New(n, -2)
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	sumBig := WsBigTotal.Add(CurRec.ArAmt)
	WsBigTotal = wrapDecimal(sumBig, 7, 2)
	WsWrapTotal = wrapDecimal(WsBigTotal, 5, 2)
	sumSafe := WsSafeTotal.Add(CurRec.ArAmt)
	if isSizeError(sumSafe, 5, 2) {
		OverflowPara()
	} else {
		WsSafeTotal = sumSafe
	}
	WsCount = (WsCount + 1) % 100
	n := CurRec.ArAmt.Shift(2).IntPart()
	halfTen := n / 20
	halfMod := halfTen % 1000000
	WsHalf = decimal.New(halfMod, -1)
	WsAmtEd = formatZZZZ9_99(CurRec.ArAmt)
	WsWrapEd = formatZZZZ9_99(WsWrapTotal)
	WsSafeEd = formatZZZZ9_99(WsSafeTotal)
	WsHalfEd = formatZZZZ9_9(WsHalf)
	fmt.Printf("%s %s %s %s %s\n", CurRec.ArAcct, WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	ReadPara()
}

func SummaryPara() {
	fmt.Printf("RECORDS: %02d\n", WsCount)
	fmt.Printf("OVERFLOWS: %02d\n", WsOverflows)
}

func OverflowPara() {
	WsOverflows = (WsOverflows + 1) % 100
}

func main() {
	MainPara()
}
